package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct {
	ScAcct  string
	ScPrin  decimal.Decimal
	ScRate  decimal.Decimal
	ScYears int64
}

var WsEofFlag string = "N"
var WsBal decimal.Decimal = decimal.NewFromInt(0)
var WsYear int64 = 0
var WsCount int64 = 0
var WsBalEd string = ""

var scRec SchedRec
var schedRecords []string
var schedIdx int

func parseDecimalField(s string, scale int32) decimal.Decimal {
	trimmed := strings.TrimSpace(s)
	if trimmed == "" {
		return decimal.NewFromInt(0)
	}
	// s may contain sign? Keep digits and sign
	// For PIC 9 only digits, but be tolerant
	neg := false
	if strings.HasPrefix(trimmed, "-") || strings.HasPrefix(trimmed, "+") {
		if trimmed[0] == '-' {
			neg = true
		}
		trimmed = trimmed[1:]
	}
	// keep only digits
	digits := ""
	for _, ch := range trimmed {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		}
	}
	if digits == "" {
		return decimal.NewFromInt(0)
	}
	// parse as integer
	d, err := decimal.NewFromString(digits)
	if err != nil {
		d = decimal.NewFromInt(0)
	}
	d = d.Shift(-scale)
	if neg {
		d = d.Neg()
	}
	return d
}

func parseIntField(s string) int64 {
	trimmed := strings.TrimSpace(s)
	if trimmed == "" {
		return 0
	}
	var v int64
	_, err := fmt.Sscan(trimmed, &v)
	if err != nil {
		// fallback manual
		n := int64(0)
		neg := false
		for i, ch := range trimmed {
			if i == 0 && ch == '-' {
				neg = true
				continue
			}
			if ch >= '0' && ch <= '9' {
				n = n*10 + int64(ch-'0')
			}
		}
		if neg {
			n = -n
		}
		return n
	}
	return v
}

func storeBal(d decimal.Decimal) decimal.Decimal {
	// PIC 9(8)V99 => total digits 10, scale 2
	// keep low-order digits: modulo 10^10 on scaled value
	// Preserve sign positive only (balance non-negative) but handle generic
	sign := 1
	if d.Sign() < 0 {
		sign = -1
		d = d.Neg()
	}
	// d is expected to have scale 2, but ensure truncated to 2
	// Use Truncate to scale 2 if needed (should already be)
	scaled := d.Shift(2).Truncate(0) // integer cents
	modulus := decimal.NewFromInt(1).Shift(10) // 10^10
	// scaled % modulus using Mod
	// decimal.Mod not perfect for large; use DivMod via big int? We'll use string fallback if needed
	// Use decimal's Mod if available; shopspring has Mod
	if scaled.Cmp(modulus) >= 0 || scaled.Cmp(decimal.NewFromInt(0).Sub(modulus)) <= 0 {
		scaled = scaled.Mod(modulus)
	}
	result := scaled.Shift(-2)
	if sign < 0 {
		result = result.Neg()
	}
	return result
}

func formatWsBalEd(v decimal.Decimal) string {
	// PIC ZZ,ZZZ,ZZ9.99  len 13
	pic := "ZZ,ZZZ,ZZ9.99"
	picLen := len(pic)
	// integer placeholders count
	intPlaceCount := 0
	fracPlaceCount := 0
	dotPos := strings.Index(pic, ".")
	if dotPos >= 0 {
		for i := 0; i < dotPos; i++ {
			if pic[i] == 'Z' || pic[i] == '9' {
				intPlaceCount++
			}
		}
		for i := dotPos + 1; i < picLen; i++ {
			if pic[i] == 'Z' || pic[i] == '9' {
				fracPlaceCount++
			}
		}
	}
	// handle sign (field is unsigned, but just in case)
	neg := v.Sign() < 0
	if neg {
		v = v.Neg()
	}
	// Ensure scale = fracPlaceCount truncated/padded
	// v should already have scale 2, but adjust
	// Get integer and fractional parts as strings
	// Use formatting to avoid float errors: get scaled integer string
	// Build integer digits zero-padded to intPlaceCount with high-order truncation
	// Approach: get total scaled integer = v * 10^fracPlaceCount
	// Then intPart = scaled / 10^frac, fracPart = scaled % 10^frac
	scalePow := decimal.NewFromInt(1).Shift(int32(fracPlaceCount))
	scaled := v.Shift(int32(fracPlaceCount)).Truncate(0)
	// Handle overflow truncation for display: integer part limited to intPlaceCount digits
	// Spec: if value has more integer digits than picture, high-order digits are dropped
	// That is already handled by storeBal, but also display would drop if still overflow.
	// Apply modulo 10^intPlaceCount to integer part
	intPart := scaled.Div(scalePow).Truncate(0)
	fracPart := scaled.Sub(intPart.Mul(scalePow))
	// modulo for int part
	modInt := decimal.NewFromInt(1).Shift(int32(intPlaceCount))
	if intPart.Cmp(modInt) >= 0 {
		intPart = intPart.Mod(modInt)
	}
	// build strings
	intStr := intPart.StringFixed(0) // no fractional
	// pad left zeros to intPlaceCount
	if len(intStr) < intPlaceCount {
		intStr = strings.Repeat("0", intPlaceCount-len(intStr)) + intStr
	} else if len(intStr) > intPlaceCount {
		intStr = intStr[len(intStr)-intPlaceCount:]
	}
	fracStr := fracPart.StringFixed(0)
	if len(fracStr) < fracPlaceCount {
		fracStr = strings.Repeat("0", fracPlaceCount-len(fracStr)) + fracStr
	} else if len(fracStr) > fracPlaceCount {
		fracStr = fracStr[len(fracStr)-fracPlaceCount:]
	}

	// Now fill pic
	out := []byte(pic)
	intIdx := 0
	fracIdx := 0
	// For Z suppression: need to know for each Z placeholder whether it should be blank
	// Determine suppression state: scanning integer placeholders left to right
	// Create array of digits for integer placeholders in order
	intDigits := []byte(intStr) // length intPlaceCount

	// Build map from pic position to placeholder order index for integer part
	// Then decide suppression
	suppressed := true
	// We need to know for each pic position that is integer placeholder, its digit
	// Iterate pic left to right up to dot
	placeholderPos := 0 // index into intDigits
	for i := 0; i < picLen; i++ {
		if pic[i] == '.' || pic[i] == ',' {
			continue
		}
		if dotPos >= 0 && i > dotPos {
			break
		}
		if pic[i] == 'Z' || pic[i] == '9' {
			d := intDigits[placeholderPos]
			placeholderPos++
			_ = d
		}
	}
	// Now second pass to fill
	intPlaceholderCounter := 0
	// To decide comma blanking: a comma is blank if all integer placeholders to its left are suppressed (blank)
	// We can compute suppression per placeholder, then for commas check if every placeholder before it is blank
	// Precompute placeholder blank flags
	blankFlags := make([]bool, intPlaceCount) // per integer placeholder in order
	sup := true
	for idx := 0; idx < intPlaceCount; idx++ {
		d := intDigits[idx]
		// Determine if this placeholder corresponds to 'Z' or '9' in pic order
		// Need mapping: find the pic character for this idx
		// Build list of pic chars for integer placeholders in order
		picIntChars := []byte{}
		for i := 0; i < picLen; i++ {
			if dotPos >= 0 && i >= dotPos {
				break
			}
			if pic[i] == 'Z' || pic[i] == '9' {
				picIntChars = append(picIntChars, pic[i])
			}
		}
		pc := picIntChars[idx]
		if pc == 'Z' {
			if sup && d == '0' {
				blankFlags[idx] = true
				// remain sup true
			} else {
				blankFlags[idx] = false
				sup = false
			}
		} else { // '9'
			blankFlags[idx] = false
			sup = false
		}
		// if all remaining digits are zero and we have mandatory 9, the 9 will show 0
		_ = sup
	}

	// Special case: if integer part is zero (all digits zero), the Z's before the 9 are blank, 9 shows 0
	// Our logic already does that.

	// Fill output
	intCounter := 0
	fracCounter := 0
	for i := 0; i < picLen; i++ {
		ch := pic[i]
		switch ch {
		case 'Z', '9':
			if dotPos >= 0 && i > dotPos {
				// fractional part
				d := fracStr[fracCounter]
				fracCounter++
				out[i] = d
			} else {
				// integer part
				d := intDigits[intCounter]
				if blankFlags[intCounter] {
					out[i] = ' '
				} else {
					out[i] = d
				}
				intCounter++
			}
		case ',':
			// comma blanks if all integer placeholders to its left are blank
			// Count placeholders left of this comma
			leftPlaceholders := 0
			for k := 0; k < i; k++ {
				if pic[k] == 'Z' || pic[k] == '9' {
					leftPlaceholders++
				}
			}
			allBlank := true
			for k := 0; k < leftPlaceholders; k++ {
				if !blankFlags[k] {
					allBlank = false
					break
				}
			}
			if allBlank {
				out[i] = ' '
			} else {
				out[i] = ','
			}
		case '.':
			out[i] = '.'
		default:
			out[i] = byte(ch)
		}
	}
	_ = intIdx
	_ = fracIdx
	_ = suppressed
	s := string(out)
	if neg {
		// For unsigned picture, COBOL would show sign? Not needed
		// Insert minus at leftmost non-space? Ignore
	}
	return s
}

func formatYear(v int64) string {
	// PIC 99 zero-padded width 2
	// Keep low-order 2 digits if overflow?
	mod := v % 100
	if mod < 0 {
		mod = -mod
	}
	return fmt.Sprintf("%02d", mod)
}

func formatCount(v int64) string {
	mod := v % 100
	if mod < 0 {
		mod = -mod
	}
	return fmt.Sprintf("%02d", mod)
}

func readSchedFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		// no file => empty
		schedRecords = []string{}
		return
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	// allow long lines
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 1024*1024)
	for scanner.Scan() {
		line := scanner.Text()
		// Remove trailing \r if present (Scanner already strips \n, but may leave \r)
		if len(line) > 0 && line[len(line)-1] == '\r' {
			line = line[:len(line)-1]
		}
		schedRecords = append(schedRecords, line)
	}
}

func parseSchedRec(raw string) SchedRec {
	// pad to 16 with spaces
	if len(raw) < 16 {
		raw = raw + strings.Repeat(" ", 16-len(raw))
	} else if len(raw) > 16 {
		raw = raw[:16]
	}
	acct := raw[0:4]
	prinStr := raw[4:11]
	rateStr := raw[11:15]
	yearsStr := raw[15:16]
	pr := parseDecimalField(prinStr, 2)
	ra := parseDecimalField(rateStr, 2)
	yr := parseIntField(yearsStr)
	return SchedRec{
		ScAcct:  acct,
		ScPrin:  pr,
		ScRate:  ra,
		ScYears: yr,
	}
}

func READ_PARA() {
	if schedIdx >= len(schedRecords) {
		WsEofFlag = "Y"
		return
	}
	raw := schedRecords[schedIdx]
	schedIdx++
	scRec = parseSchedRec(raw)
}

func PROCESS_PARA() {
	WsBal = scRec.ScPrin
	// store to balance field (handle overflow) – though direct move truncates
	WsBal = storeBal(WsBal.Truncate(2))

	for WsYear = 1; WsYear <= scRec.ScYears; WsYear++ {
		// COMPUTE WS-BAL ROUNDED = WS-BAL * (1 + SC-RATE / 100)
		factor := decimal.NewFromInt(1).Add(scRec.ScRate.Shift(-2))
		computed := WsBal.Mul(factor)
		rounded := computed.Round(2)
		WsBal = storeBal(rounded)

		WsBalEd = formatWsBalEd(WsBal)
		// DISPLAY SC-ACCT " Y" WS-YEAR " " WS-BAL-ED
		yearStr := formatYear(WsYear)
		fmt.Printf("%s Y%s %s\n", scRec.ScAcct, yearStr, WsBalEd)
	}
	WsBalEd = formatWsBalEd(WsBal)
	fmt.Printf("%s FINAL %s\n", scRec.ScAcct, WsBalEd)
	WsCount++
	READ_PARA()
}

func MAIN_PARA() {
	readSchedFile()
	schedIdx = 0
	READ_PARA()
	for WsEofFlag != "Y" {
		PROCESS_PARA()
	}
	// DISPLAY "SCHEDULES: " WS-COUNT
	fmt.Printf("SCHEDULES: %s\n", formatCount(WsCount))
}

func main() {
	MAIN_PARA()
}

